package com.bitewise.service;
import com.bitewise.entity.*; import com.bitewise.repository.*; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import java.util.UUID;
@Service public class CurrentUserService { private final UserRepository users; private final BusinessRepository businesses; public CurrentUserService(UserRepository u,BusinessRepository b){users=u;businesses=b;} public User user(){String email=SecurityContextHolder.getContext().getAuthentication().getName();return users.findByEmailIgnoreCase(email).orElseThrow(()->new IllegalStateException("Authenticated user not found"));} public Business business(){return businesses.findByUserId(user().getId()).orElseThrow(()->new IllegalStateException("Business profile not found"));} public UUID businessId(){return business().getId();} }
